pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(user != address(0));
        depositAmount = bound(depositAmount, 1, address(this).balance);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        // Record initial balances
        uint256 initialUserBalance = user.balance;
        uint256 initialContractBalance = address(c).balance;

        // Deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Withdraw
        vm.prank(user);
        c.withdraw(withdrawAmount);

        // Check invariant: total balance of user + contract is unchanged from before deposit
        // Before deposit: initialUserBalance + initialContractBalance
        // After deposit + withdraw: user.balance + address(c).balance
        assertTrue(
            user.balance + address(c).balance == initialUserBalance + initialContractBalance
        );
    }
}

