pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0));
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 balanceAfterDeposit = address(c).balance;
        // If we try to withdraw more than the contract balance, it will revert
        // So we bound the withdraw to the contract balance
        uint256 withdrawAmount = depositAmount > balanceAfterDeposit ? balanceAfterDeposit : depositAmount;
        vm.prank(caller);
        c.withdraw(withdrawAmount);
        // After withdraw, the caller's contract balance should be at most what they deposited
        uint256 callerBalance = address(c).balance;
        assertTrue(callerBalance <= depositAmount);
    }
}

